var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`CHURCH`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`HARAB_QLIPHOTH_WEDDING_NULL`,text:{KOREA:`한낱 피조물에게 마음을 빼앗기는 굴욕… 주인님 같은 분께서는 쉽게 느낄 고통이 아니죠. 그렇다면 저도 조금 더 진심을 담아 대해 드려야겠군요. 이혼은 꿈도 꾸지 마세요, 여보.`,JPN:`一介の被造物に心を奪われる屈辱……ご主人様のような方にこの苦痛はわかりづらいでしょう。ならば、私ももう少し心を込めて接しないといけませんね。離婚は絶対認めませんわ、あなた。`,ENG:`The embarrassment of falling for a mere creation... Someone like you wouldn’t feel that very often. So, in return, I’ll have to get a bit more serious with you too. Don’t you even dream of divorcing me, Sweet Heart.`,TWN:`被區區受造物偷走心的屈辱…主人你無法理解這種痛苦吧。既然如此，那我也要更認真地對待你，離婚這件事想都別想，老公。`},stage:{bg:`CHURCH`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`HARAB_QLIPHOTH_WEDDING_NULL`,face:`UNIT_IDLE`,hologram:!1},R:null}}}];export{e as default};